DO $$
DECLARE
  rec RECORD;
  cur_status INT;
BEGIN
  FOR rec IN SELECT * FROM milestone_events ORDER BY event_id LOOP
    SELECT milestone_status INTO cur_status FROM shipments WHERE shipment_id = rec.shipment_id;
    IF rec.event_type = 1 AND cur_status = 0 THEN
      UPDATE shipments SET milestone_status = 1, last_change_ts = rec.event_timestamp WHERE shipment_id = rec.shipment_id;
    ELSIF rec.event_type = 2 AND cur_status = 1 THEN
      UPDATE shipments SET milestone_status = 2, last_change_ts = rec.event_timestamp WHERE shipment_id = rec.shipment_id;
    ELSIF rec.event_type = 2 AND cur_status = 2 THEN
      UPDATE shipments SET milestone_status = 3, last_change_ts = rec.event_timestamp WHERE shipment_id = rec.shipment_id;
    ELSIF rec.event_type = 3 AND cur_status = 1 THEN
      UPDATE shipments SET milestone_status = 0, last_change_ts = rec.event_timestamp WHERE shipment_id = rec.shipment_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM shipments ORDER BY shipment_id;
